import { describe, expect, it } from '@jest/globals';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import {
  GrantRecordError,
  envelopeParameter,
  envelopeProblem,
  StrictJsonError,
  parseExportLines,
  parseJson,
  receivedCanonical,
  signedAsReceived,
  useProblem,
  verifyEvidenceEvents,
} from '../src/index.js';
import type { CapabilityGrant, ExecutorKeyInfo, GrantExecutionEvidence, PreviousUse } from '../src/index.js';

/**
 * The `grants` conformance suite (Genesis Mesh 1.6.0), generated by the Python
 * reference (genesismesh/conformance/grants_vectors.py) and copied unchanged:
 * the signed forms of the new records and the revocation feed, envelope
 * parameters and envelopes with the number rules, the use rules in their
 * order, and exports holding grants, uses and revocations.
 *
 * The suite's `na_only_kinds` (`issuance`: the NA's own check, deciding every
 * gate of every applied policy over a grant's envelope) are skipped, as the
 * suite says an SDK does: this one neither issues grants nor evaluates
 * policies.
 */
interface Vector {
  id: string;
  kind: string;
  description: string;
  model?: string;
  record?: Record<string, unknown>;
  public_key?: string;
  input?: Record<string, unknown>;
  expected: Record<string, unknown>;
}

const raw = readFileSync(fileURLToPath(new URL('./fixtures/conformance/grants.json', import.meta.url)), 'utf-8');
const suite = parseJson(raw) as { suite: string; version: string; na_only_kinds: string[]; vectors: Vector[] };
const NA_RULES = new Set(suite.na_only_kinds);

function outcome(v: Vector): Record<string, unknown> {
  const input = v.input ?? {};
  switch (v.kind) {
    case 'canonical_form': {
      const body = receivedCanonical(v.model!, v.record!);
      return { canonical: body, digest: createHash('sha256').update(body, 'utf-8').digest('hex') };
    }
    case 'verify_record':
      return { valid: signedAsReceived(v.model!, v.record!, [v.public_key!]) };
    case 'envelope_parameter':
      try {
        // A parameter given as text is read as every implementation reads JSON (2^64 is refused).
        const parameter = 'parameter_json' in input ? parseJson(input['parameter_json'] as string) : input['parameter'];
        return { valid: true, normalized: envelopeParameter(parameter) };
      } catch (err) {
        if (!(err instanceof GrantRecordError) && !(err instanceof StrictJsonError)) throw err;
        return { valid: false };
      }
    case 'envelope': {
      const envelope = Object.fromEntries(Object.entries(input['envelope'] as Record<string, unknown>)
        .map(([name, spec]) => [name, envelopeParameter(spec)]));
      return { within: envelopeProblem(envelope, input['request_parameters']) === null };
    }
    case 'use': {
      const use = input['use'] as GrantExecutionEvidence;
      const head = input['token_head'] as { digest: string; executed_at: string } | null;
      const found = useProblem(use, {
        grant: (input['grant'] as CapabilityGrant | null) ?? null,
        previous: (input['previous'] as PreviousUse | null) ?? null,
        admitted: (input['admitted'] as number | null) ?? null,
        tokenHead: head, tokenKeys: input['na_public_keys'] as string[], rawToken: use.time_token,
        revokedAt: (input['revoked_at'] as string | null) ?? null, recordedAt: (input['recorded_at'] as string | null) ?? null,
      });
      return { code: found?.code ?? null };
    }
    case 'verify_export': {
      const result = verifyEvidenceEvents(parseExportLines(input['lines'] as string), {
        naPublicKeys: input['na_public_keys'] as string[], executorKeys: input['executor_keys'] as ExecutorKeyInfo[],
        contiguous: (input['contiguous'] as boolean | undefined) ?? true,
      });
      const failures = [...new Map(result.failures.map(f => [`${f.store_sequence}\u0000${f.reason}`, f])).values()]
        .map(f => ({ store_sequence: f.store_sequence, reason: f.reason }))
        .sort((a, b) => (a.store_sequence ?? 0) - (b.store_sequence ?? 0) || (a.reason < b.reason ? -1 : 1));
      const counts = Object.fromEntries((['executions', 'observations', 'judgements', 'quarantined', 'grants',
        'grant_executions', 'grant_revocations'] as const).filter(k => result[k] !== undefined).map(k => [k, result[k]]));
      return { verified: result.verified, failures, counts };
    }
    default:
      throw new Error(`unknown vector kind ${v.kind}`);
  }
}

describe('grants conformance vectors (v1.6.0)', () => {
  it('is the grants suite, all 158 vectors, strict JSON', () => {
    expect(suite.suite).toBe('grants');
    expect(suite.version).toBe('1.6.0');
    expect(suite.vectors).toHaveLength(158);
    // The NA's issuance check: 59 vectors this SDK does not run (see above).
    expect(suite.na_only_kinds).toEqual(['issuance']);
    expect(suite.vectors.filter(v => NA_RULES.has(v.kind))).toHaveLength(59);
  });

  for (const v of suite.vectors.filter(v => !NA_RULES.has(v.kind))) {
    it(`${v.id}: ${v.description}`, () => {
      expect(outcome(v)).toEqual(v.expected);
    });
  }
});
